<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { Plus, Download } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import CityAnalyticsDrawer from '../components/CityAnalyticsDrawer.vue';
import CityAnalyticsRulesDrawer from '../components/CityAnalyticsRulesDrawer.vue';
import { cityApi, day, draft, err, nf, notifyDownload, p, text, time, tone, useCityQuery } from '../city-analytics';
import '../city-analytics.css';
const session=useSessionStore(),c=useCityQuery({enterpriseId:'',taskId:'',status:'',q:''});
const can=(permission:string)=>!!session.user?.permissions.includes(permission);
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),options=ref<any>({enterprises:[]}),batches=ref<any[]>([]),rules=ref<any>(),optionsError=ref('');
const detail=ref<any>(),detailError=ref(''),detailLoading=ref(false),tab=ref('scores'),rulesOpen=ref(false),createOpen=ref(false),saving=ref(false),createError=ref(''),actionOpen=ref(false),actionType=ref(''),comment=ref(''),actionError=ref('');
const appealsOpen=ref(false),appeals=ref<any[]>([]),appealsError=ref(''),appealsLoading=ref(false),appealTarget=ref<any>(),appealAction=ref('ACCEPT'),appealOpen=ref(false),appealComment=ref(''),appealError=ref(''),sourceRecord=ref<any>(),sourceOpen=ref(false),sourceLoading=ref(false),sourceError=ref('');
let loadId=0,detailId=0;
const visible=computed({get:()=>!!c.id.value,set:v=>{if(!v)void c.close();}}),evidence=computed(()=>Array.isArray(detail.value?.evidence)?detail.value.evidence:detail.value?.evidence?.items??[]),coverage=computed(()=>detail.value?.evidence?.coverage);
const previousMonth=()=>{const current=day(new Date().toISOString()),last=day(new Date(new Date(current.slice(0,7)+'-01T00:00:00+08:00').getTime()-86400000).toISOString());return [last.slice(0,7)+'-01',last];};
const draftForm=draft(`wrc-city-evaluation-${session.user?.id}`,{name:'',periodType:'MONTHLY',dates:previousMonth(),enterpriseId:''});const form=draftForm.value;
async function load(){const id=++loadId;loading.value=true;error.value='';try{const result=await api<any>(`${cityApi}/evaluations?${c.params()}`);if(id===loadId){rows.value=result.items;total.value=result.total;if(!rows.value.length&&total.value&&c.page.value>1)void c.paginate(1);}}catch(e){if(id===loadId)error.value=err(e);}finally{if(id===loadId)loading.value=false;}}
async function loadOptions(){optionsError.value='';try{const [o,b,r]=await Promise.all([api<any>(`${cityApi}/options`),api<any[]>(`${cityApi}/evaluations/batches`),api<any>(`${cityApi}/evaluations/rules`)]);options.value=o;batches.value=b;rules.value=r;}catch(e){optionsError.value=err(e);}}
async function search(){const before=c.queryKey.value;await c.search();if(before===c.queryKey.value)await load();}
async function reset(){const before=c.queryKey.value;await c.reset();if(before===c.queryKey.value)await load();}
async function loadDetail(){const id=++detailId;detail.value=null;detailError.value='';if(!c.id.value)return;detailLoading.value=true;try{const result=await api(`${cityApi}/evaluations/${c.id.value}`);if(id===detailId)detail.value=result;}catch(e){if(id===detailId)detailError.value=err(e);}finally{if(id===detailId)detailLoading.value=false;}}
async function create(){if(!form.name.trim()||form.dates?.length!==2)return ElMessage.warning('请填写评价名称并选择周期');if(!rules.value?.active)return ElMessage.warning('请先核对并发布评价规则');saving.value=true;createError.value='';try{const result=await api<any>(`${cityApi}/evaluations`,{method:'POST',body:JSON.stringify({name:form.name.trim(),periodType:form.periodType,from:form.dates[0],to:form.dates[1],enterpriseId:form.enterpriseId||undefined,rulesVersion:rules.value.versionLabel})});createOpen.value=false;draftForm.clear();await loadOptions();c.filters.taskId=result.id;await search();ElMessage.success(`已生成${result.count}家企业评价，${result.pending}家需核对数据`);}catch(e){createError.value=err(e);}finally{saving.value=false;}}
function openCreate(){if(!form.name)form.name=`${form.dates?.[0]?.slice(0,7)??''}企业月度评价`;createError.value='';createOpen.value=true;}
function act(kind:string){actionType.value=kind;comment.value='';actionError.value='';actionOpen.value=true;}
async function action(){if(!comment.value.trim())return ElMessage.warning('请填写办理意见');saving.value=true;actionError.value='';try{detail.value=await api(`${cityApi}/evaluations/${c.id.value}/actions`,{method:'POST',body:JSON.stringify({action:actionType.value,comment:comment.value.trim(),version:detail.value.version})});actionOpen.value=false;ElMessage.success(`${text(actionType.value)}已完成`);await load();}catch(e){actionError.value=err(e);}finally{saving.value=false;}}
async function loadAppeals(){appealsLoading.value=true;appealsError.value='';try{const result=await api<any>('/analytics/appeals?'+p({status:'SUBMITTED',page:1,pageSize:200}));appeals.value=result.items;}catch(e){appealsError.value=err(e);}finally{appealsLoading.value=false;}}
function reviewAppeal(row:any,action:string){appealTarget.value=row;appealAction.value=action;appealComment.value='';appealError.value='';appealOpen.value=true;}
async function submitAppeal(){if(!appealComment.value.trim())return ElMessage.warning('请填写申诉复核意见');saving.value=true;appealError.value='';try{await api(`/analytics/appeals/${appealTarget.value.id}/review`,{method:'POST',body:JSON.stringify({action:appealAction.value,comment:appealComment.value.trim()})});appealOpen.value=false;await Promise.all([loadAppeals(),load()]);if(c.id.value)await loadDetail();ElMessage.success(appealAction.value==='ACCEPT'?'已受理，评价须重新核定后复核发布':'已记录驳回意见');}catch(e){appealError.value=err(e);}finally{saving.value=false;}}
async function source(item:any){sourceRecord.value=item;sourceOpen.value=true;sourceError.value='';if(item.kind==='OPERATION'){sourceLoading.value=true;try{sourceRecord.value={...item,...await api<any>(`${cityApi}/operations/records/${item.id}`)};}catch(e){sourceError.value=err(e);}finally{sourceLoading.value=false;}}}
function sourceLink(item:any){const eventPermissions:any={ALERT:'safety:alert:read',ACCIDENT:'safety:accident:read',VIOLATION:'safety:violation:read',OFFLINE:'safety:offline:read'};if(eventPermissions[item.kind]&&can(eventPermissions[item.kind]))void c.router.push({path:'/safety/events',query:{eventKind:item.kind,eventId:item.id}});else if(item.kind==='RECTIFICATION'&&can('safety:emergency:read'))void c.router.push({path:'/safety/emergency',query:{taskId:item.id,taskType:'RECTIFICATION'}});else void source(item);}
async function rulesChanged(){await loadOptions();}
watch(c.queryKey,()=>void load(),{immediate:true});watch(c.id,()=>{tab.value='scores';void loadDetail();},{immediate:true});void loadOptions();void loadAppeals();
</script>
<template><section class="ca-page ca-collection" :class="{'ca-has-detail':!!c.id.value}" :style="{'--ca-detail-width':'640px'}" aria-label="企业评价">
 <QueryPanel :loading="loading" @search="search" @reset="reset"><QueryField label="企业"><el-select v-model="c.filters.enterpriseId" clearable filterable placeholder="全部企业" aria-label="企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></QueryField><QueryField label="评价批次"><el-select v-model="c.filters.taskId" clearable filterable placeholder="全部批次" aria-label="评价批次"><el-option v-for="b in batches" :key="b.id" :label="b.name" :value="b.id"/></el-select></QueryField><QueryField label="状态"><el-select v-model="c.filters.status" clearable placeholder="全部状态" aria-label="状态"><el-option v-for="s in ['DRAFT','DATA_PENDING','REVIEWED','PUBLISHED','UNDER_REVIEW']" :key="s" :label="text(s)" :value="s"/></el-select></QueryField><QueryField label="关键词" keyword><el-input v-model="c.filters.q" clearable placeholder="企业、评价名称或编号" aria-label="关键词"/></QueryField></QueryPanel>
 <div v-if="optionsError" class="ca-form-error" role="alert">筛选选项加载失败：{{optionsError}} <el-button link @click="loadOptions">重试</el-button></div>
 <article class="ca-card"><header class="ca-card-title"><h2>企业评价</h2><span class="ca-count">{{total}}</span><div class="ca-tools"><el-button @click="rulesOpen=true">评价规则</el-button><el-button @click="appealsOpen=true;loadAppeals()">申诉复核<el-badge v-if="appeals.length" :value="appeals.length" style="margin-left:10px"/></el-button><el-button v-if="can('analytics:evaluation:generate')" type="primary" :icon="Plus" @click="openCreate">新建评价</el-button></div></header>
 <div v-if="error" class="ca-error" role="alert"><strong>评价结果暂时无法加载</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="ca-table" v-loading="loading"><el-table :data="rows" height="100%" :row-class-name="({row}:any)=>row.id===c.id.value?'ca-selected':''" empty-text="当前条件暂无评价结果"><el-table-column label="运营企业 / 评价周期" min-width="300"><template #default="{row}"><el-button link class="ca-company" @click="c.open(row.id)">{{row.enterprise.name}}</el-button><span class="ca-secondary">{{row.task.name}} · {{day(row.task.periodStart)}} — {{day(row.task.periodEnd)}}</span></template></el-table-column><el-table-column label="周期评价分" min-width="130" align="right"><template #default="{row}"><strong>{{nf(row.totalScore)}}</strong><small v-if="row.totalScore!=null"> 分</small></template></el-table-column><el-table-column label="等级" width="90" align="center"><template #default="{row}"><el-tag v-if="row.grade" :type="row.grade==='A'?'success':'primary'">{{row.grade}}</el-tag><span v-else>—</span></template></el-table-column><el-table-column label="状态" min-width="150"><template #default="{row}"><el-tag :type="tone(row.status)">{{text(row.status)}}</el-tag></template></el-table-column><el-table-column label="申诉" width="110"><template #default="{row}">{{row.appeals.some((a:any)=>a.status==='SUBMITTED')?'待复核':row.appeals.length?'有记录':'—'}}</template></el-table-column><el-table-column label="操作" :width="c.narrow.value?110:220" fixed="right"><template #default="{row}"><el-button link type="primary" @click="c.open(row.id)">{{row.status==='DATA_PENDING'?'核对数据':'详情'}}</el-button></template></el-table-column></el-table></div>
 <footer class="ca-foot"><span>评价分按周期计算；点击详情查看评分依据。</span><el-pagination :current-page="c.page.value" :page-size="c.pageSize.value" :total="total" layout="total, sizes, prev, pager, next" :page-sizes="[10,20,50]" @current-change="c.paginate" @size-change="(v:number)=>c.paginate(1,v)"/></footer></article>
 <CityAnalyticsDrawer v-model="visible" title="评价详情"><div v-if="detailError" class="ca-error" role="alert"><strong>评价详情暂时无法加载</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><el-skeleton v-else-if="detailLoading" :rows="12" animated/><template v-else-if="detail"><h2 class="ca-detail-title">{{detail.enterprise.name}}</h2><span class="ca-muted">{{detail.task.name}}</span><el-tag :type="tone(detail.status)" style="float:right">{{text(detail.status)}}</el-tag><div class="ca-score"><div><span class="ca-muted">周期综合评价</span><div><strong>{{nf(detail.totalScore)}}</strong> 分</div></div><el-tag v-if="detail.grade" :type="detail.grade==='A'?'success':'primary'">{{detail.grade}}级</el-tag><span class="ca-score-side">{{detail.rulesVersion}}</span></div><dl class="ca-detail-meta"><dt>评价周期</dt><dd>{{day(detail.task.periodStart)}} — {{day(detail.task.periodEnd)}}</dd><dt>复核人</dt><dd>{{detail.reviewedByName||'—'}}</dd><dt>发布时间</dt><dd>{{time(detail.publishedAt)}}</dd></dl><el-alert v-if="detail.quality.length" type="warning" :closable="false" title="当前结果需核对数据，完成后重新计算，暂不能发布。"/>
 <el-tabs v-model="tab"><el-tab-pane label="评分明细" name="scores"/><el-tab-pane :label="`依据记录（${evidence.length}）`" name="evidence"/><el-tab-pane :label="`申诉记录（${detail.appeals.length}）`" name="appeals"/></el-tabs>
 <template v-if="tab==='scores'"><div v-for="[key,name] in [['safetyScore','安全表现'],['complianceScore','合规情况'],['operationScore','运行表现']]" :key="key" class="ca-dimension"><span>{{name}}</span><el-progress :percentage="detail[key]??0" :show-text="false" :stroke-width="12"/><strong>{{nf(detail[key])}}</strong><span v-if="detail.task.rulesVersion" class="ca-muted">权重{{nf(detail.breakdown.filter((b:any)=>b.dimension===({safetyScore:'SAFETY',complianceScore:'COMPLIANCE',operationScore:'OPERATION'} as any)[key]).reduce((s:number,b:any)=>s+b.weight,0))}}%</span><span v-else class="ca-muted">权重未留存</span></div><table class="ca-detail-table"><thead><tr><th>指标</th><th>指标值</th><th>得分</th><th>依据</th></tr></thead><tbody><tr v-for="(b,index) in detail.breakdown" :key="index"><td>{{b.name}}<span class="ca-secondary">{{b.rule}}</span></td><td>{{nf(b.value)}}</td><td>{{nf(b.score)}}</td><td><el-button v-if="evidence.length" link type="primary" @click="tab='evidence'">查看记录</el-button><span v-else class="ca-muted">未留存引用</span></td></tr></tbody></table><div v-for="(q,index) in detail.quality" :key="index" class="ca-form-error"><strong>{{q.name}}</strong>：{{q.reason}}</div><p v-if="coverage" class="ca-note">本期运行记录{{coverage.recordCount}}条，联网日统计{{coverage.validOnlineRows}} / {{coverage.onlineRows}}条有效，接入车辆{{coverage.vehicles}}辆。在线率按有效上报分钟加权计算。</p><p v-else class="ca-note">此为历史评价，原始依据引用和规则版本未完整留存。</p><el-collapse v-if="detail.history.length"><el-collapse-item title="办理与发布留存记录" name="history"><article v-for="(h,i) in detail.history" :key="i" class="ca-history"><header><strong>{{text(h.action)}}</strong><span class="ca-muted">{{h.actorName}} · {{time(h.at)}}</span></header><p>{{h.comment}}</p><span v-if="h.publishedSnapshot" class="ca-muted">本次已留存得分、规则及来源依据。</span></article></el-collapse-item></el-collapse></template>
 <template v-else-if="tab==='evidence'"><el-empty v-if="!evidence.length" description="历史结果未留存来源引用" :image-size="70"/><el-table v-else :data="evidence" max-height="520" empty-text="暂无依据记录"><el-table-column label="依据记录" min-width="210"><template #default="{row}"><strong>{{row.title||text(row.kind)}}</strong><span class="ca-secondary">{{row.businessNo||text(row.kind)}} · {{time(row.at)}}</span></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="sourceLink(row)">查看依据</el-button></template></el-table-column></el-table></template>
 <template v-else><el-empty v-if="!detail.appeals.length" description="暂无申诉记录" :image-size="70"/><article v-for="a in detail.appeals" :key="a.id" class="ca-history"><header><strong>{{a.businessNo}}</strong><el-tag :type="tone(a.status)">{{text(a.status)}}</el-tag></header><p>{{a.reason}}</p><p v-if="a.evidence">补充依据：{{a.evidence}}</p><span class="ca-muted">{{a.submittedByName}} · {{time(a.createdAt)}}</span><p v-if="a.reviewComment">复核意见：{{a.reviewComment}}</p><div v-if="a.status==='SUBMITTED'&&can('analytics:evaluation:review')"><el-button type="primary" @click="reviewAppeal(a,'ACCEPT')">受理重新核定</el-button><el-button @click="reviewAppeal(a,'REJECT')">驳回</el-button></div></article></template>
 </template><template #footer><el-button @click="visible=false">关闭</el-button><el-dropdown v-if="detail" trigger="click" @command="(v:string)=>v==='export'?notifyDownload(`${cityApi}/evaluations/${detail.id}/export`):act(v)"><el-button>更多操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="export">导出评价</el-dropdown-item><el-dropdown-item v-if="detail.status!=='PUBLISHED'&&can('analytics:evaluation:generate')" command="RECALCULATE">重新计算</el-dropdown-item><el-dropdown-item v-if="['DRAFT','REVIEWED','UNDER_REVIEW'].includes(detail.status)&&can('analytics:evaluation:review')" command="RETURN">退回核对</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="detail&&['DRAFT','UNDER_REVIEW'].includes(detail.status)&&!detail.quality.length&&detail.task.rulesVersion&&can('analytics:evaluation:review')" type="primary" @click="act('REVIEW')">复核通过</el-button><el-button v-if="detail?.status==='REVIEWED'&&can('analytics:evaluation:publish')" type="primary" @click="act('PUBLISH')">发布评价</el-button><el-button v-if="detail?.status==='DATA_PENDING'&&can('analytics:evaluation:generate')" type="primary" @click="act('RECALCULATE')">核对后重新计算</el-button></template></CityAnalyticsDrawer>
 <CityAnalyticsRulesDrawer v-model="rulesOpen" kind="evaluation" @changed="rulesChanged"/>
 <CityAnalyticsDrawer v-model="appealsOpen" title="申诉复核" width="720px"><div v-if="appealsError" class="ca-error"><span>{{appealsError}}</span><el-button @click="loadAppeals">重试</el-button></div><el-skeleton v-else-if="appealsLoading" :rows="8" animated/><el-empty v-else-if="!appeals.length" description="暂无待复核申诉" :image-size="70"/><article v-for="a in appeals" v-else :key="a.id" class="ca-history"><header><strong>{{a.enterprise?.name}}</strong><span class="ca-muted">{{a.businessNo}}</span></header><p>{{a.reason}}</p><p v-if="a.evidence">补充依据：{{a.evidence}}</p><div v-if="can('analytics:evaluation:review')"><el-button type="primary" @click="reviewAppeal(a,'ACCEPT')">受理重新核定</el-button><el-button @click="reviewAppeal(a,'REJECT')">驳回</el-button></div></article><template #footer><el-button @click="appealsOpen=false">关闭</el-button></template></CityAnalyticsDrawer>
 <el-dialog v-model="createOpen" title="新建企业评价" width="620px" class="ca-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><el-alert v-if="!rules?.active" type="info" :closable="false" title="请先核对并发布评价规则。"/><el-form label-position="top"><el-form-item label="评价名称" required><el-input v-model="form.name" maxlength="150" aria-label="评价名称"/></el-form-item><el-form-item label="评价周期" required><el-date-picker v-model="form.dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" aria-label="评价周期"/></el-form-item><el-form-item label="周期类型"><el-select v-model="form.periodType" aria-label="周期类型"><el-option label="月度评价" value="MONTHLY"/><el-option label="季度评价" value="QUARTERLY"/><el-option label="年度评价" value="ANNUAL"/><el-option label="自定义周期" value="SPECIAL"/></el-select></el-form-item><el-form-item label="评价企业"><el-select v-model="form.enterpriseId" clearable filterable placeholder="全部授权企业" aria-label="评价企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item></el-form><p class="ca-note">使用规则{{rules?.versionLabel}}；生成后为草稿，需数据核对、复核后发布。未提交内容自动保留。</p><div v-if="createError" class="ca-form-error" role="alert">{{createError}}</div><template #footer><el-button :disabled="saving" @click="createOpen=false">取消</el-button><el-button v-if="!rules?.active" @click="createOpen=false;rulesOpen=true">配置评价规则</el-button><el-button v-else type="primary" :loading="saving" @click="create">生成评价草稿</el-button></template></el-dialog>
 <el-dialog v-model="actionOpen" :title="text(actionType)" width="520px" class="ca-dialog" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><p>{{detail?.enterprise.name}} · {{detail?.task.name}}</p><p v-if="actionType==='PUBLISH'" class="ca-note">发布后留存本次评分和依据，企业可查看并提交申诉。</p><el-input v-model="comment" type="textarea" :rows="4" maxlength="2000" placeholder="请填写办理意见" aria-label="办理意见"/><div v-if="actionError" class="ca-form-error" role="alert">{{actionError}}</div><template #footer><el-button :disabled="saving" @click="actionOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="action">确认{{text(actionType)}}</el-button></template></el-dialog>
 <el-dialog v-model="appealOpen" :title="appealAction==='ACCEPT'?'受理申诉并重新核定':'驳回申诉'" width="520px" class="ca-dialog" :close-on-click-modal="false"><p>{{appealTarget?.reason}}</p><el-input v-model="appealComment" type="textarea" :rows="4" maxlength="2000" aria-label="申诉复核意见" placeholder="请填写复核意见"/><div v-if="appealError" class="ca-form-error" role="alert">{{appealError}}</div><template #footer><el-button :disabled="saving" @click="appealOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitAppeal">确认复核</el-button></template></el-dialog>
 <el-dialog v-model="sourceOpen" title="评价依据" width="620px" class="ca-dialog"><el-skeleton v-if="sourceLoading" :rows="6" animated/><p v-else-if="sourceError" class="ca-form-error">{{sourceError}}</p><template v-else-if="sourceRecord"><h3>{{sourceRecord.businessNo||sourceRecord.title}}</h3><dl class="ca-detail-meta"><dt>记录类型</dt><dd>{{text(sourceRecord.kind)}}</dd><dt>记录时间</dt><dd>{{time(sourceRecord.at||sourceRecord.startedAt)}}</dd><template v-if="sourceRecord.kind==='ONLINE'"><dt>在线分钟</dt><dd>{{nf(sourceRecord.onlineMinutes)}}</dd><dt>统计分钟</dt><dd>{{nf(sourceRecord.totalMinutes)}}</dd><dt>上报在线率</dt><dd>{{nf(sourceRecord.onlineRate)}}%</dd></template><template v-if="sourceRecord.kind==='OPERATION'"><dt>运行车辆</dt><dd>{{sourceRecord.vehicle?.name}}</dd><dt>运行里程</dt><dd>{{nf(sourceRecord.mileage)}} km</dd><dt>运行时长</dt><dd>{{nf(sourceRecord.durationMinutes)}}分钟</dd><dt>起终点</dt><dd>{{sourceRecord.startAddress||'—'}} → {{sourceRecord.endAddress||'—'}}</dd></template><template v-if="sourceRecord.status"><dt>事项状态</dt><dd>{{text(sourceRecord.status)}}</dd></template></dl></template><template #footer><el-button @click="sourceOpen=false">关闭</el-button></template></el-dialog>
</section></template>
